import ImageCard from "./components/ImageCard";
import "./style.css";

function App() {

  const images = [

    {
      id:1,
      title:"Mountain",
      description:"Beautiful mountain scenery.",
      image:"https://picsum.photos/400/300?1"
    },

    {
      id:2,
      title:"Beach",
      description:"Relaxing beach view.",
      image:"https://picsum.photos/400/300?2"
    },

    {
      id:3,
      title:"Forest",
      description:"Green forest landscape.",
      image:"https://picsum.photos/400/300?3"
    },

    {
      id:4,
      title:"City",
      description:"Amazing city skyline.",
      image:"https://picsum.photos/400/300?4"
    },

    {
      id:5,
      title:"Waterfall",
      description:"Natural waterfall beauty.",
      image:"https://picsum.photos/400/300?5"
    },

    {
      id:6,
      title:"Sunset",
      description:"Colorful sunset view.",
      image:"https://picsum.photos/400/300?6"
    }

  ];


  return (

    <>

      <h1 className="heading">
        Image Gallery
      </h1>

      <div className="gallery">

        {images.map((item) => (

          <ImageCard
            key={item.id}
            title={item.title}
            description={item.description}
            image={item.image}
          />

        ))}

      </div>

    </>

  );

}

export default App;
